-- 로그를 담을 것을 만든다

@Slf4j
@Component
public class TraceV1 {

    public TraceStatus begin(String message) {
        long startTimeMs = System.currentTimeMillis();
        log.info("[{}] {}", "", message);
        return new TraceStatus(startTimeMs, message);
    }

    public void end(TraceStatus status) {
        complete(status, null);
    }

    public void exception(TraceStatus status, Exception e) {
        complete(status, e);
    }

    private void complete(TraceStatus status, Exception e) {
        long resultTimeMs = System.currentTimeMillis() - status.getStartTimeMs();
        if (e == null) log.info("[{}] {} time={}ms", "", status.getMessage(), resultTimeMs);
        else log.info("[{}] {} time={}ms ex={}", "", status.getMessage(), resultTimeMs, e.toString());
    }
}

